<?php
defined('BASEPATH') OR exit('No direct script access allowed');

/**
 * Lifecare Diagnostic Center — Standard CSV Export Engine
 * 
 * Generates RFC 4180-compliant CSV files with:
 * - UTF-8 Byte Order Mark (BOM) for complete Excel and Unicode/Bengali support
 * - CSV / Formula Injection protection (OWASP compliant)
 * - Metadata header (Organization, Report Title, Period, Generated By/Time)
 * - Summary KPI section
 * - Formatted column data and totals
 * - Memory-efficient php://output streaming
 * 
 * @package    Lifecare Hospital ERP
 * @subpackage Libraries
 */
class ReportCsv
{
    protected $ci;

    public function __construct()
    {
        if (function_exists('get_instance')) {
            $this->ci =& get_instance();
        }
    }

    /**
     * Generate and stream CSV to browser
     * 
     * @param array  $payload  Standardized report payload
     * @param string $filename Download filename
     * @return void
     */
    public function export(array $payload, $filename = '')
    {
        if (empty($filename)) {
            $key = !empty($payload['report_key']) ? $payload['report_key'] : 'report';
            $filename = 'lifecare_' . preg_replace('/[^a-zA-Z0-9_-]/', '_', $key) . '_' . date('Ymd_His') . '.csv';
        }

        // Set clean download headers
        if (!headers_sent()) {
            header('Content-Type: text/csv; charset=utf-8');
            header('Content-Disposition: attachment; filename="' . $filename . '"');
            header('Pragma: no-cache');
            header('Expires: 0');
            header('Cache-Control: must-revalidate, post-check=0, pre-check=0');
        }

        $out = fopen('php://output', 'w');

        // 1. Output UTF-8 BOM for Excel Bengali/Unicode compatibility
        fputs($out, "\xEF\xBB\xBF");

        $org_name = !empty($payload['branding']['hospital_name']) ? $payload['branding']['hospital_name'] : 'Lifecare Diagnostic Center';
        $report_title = !empty($payload['report_title']) ? $payload['report_title'] : 'Report';
        $period_label = !empty($payload['date_range']) ? $payload['date_range'] : (!empty($payload['period_label']) ? $payload['period_label'] : 'All Available Dates');
        $generated_at = !empty($payload['generated_at']) ? $payload['generated_at'] : date('d/m/Y h:i A');
        $generated_by = !empty($payload['generated_by']) ? $payload['generated_by'] : 'System User';
        $currency = !empty($payload['currency']) ? $payload['currency'] : 'BDT';

        // 2. Report Header Block
        fputcsv($out, [$org_name]);
        fputcsv($out, [$report_title . (!empty($payload['report_subtitle']) ? ' - ' . $payload['report_subtitle'] : '')]);
        fputcsv($out, ['Period / Date Range:', $period_label]);
        fputcsv($out, ['Generated On:', $generated_at, 'Generated By:', $generated_by]);
        fputcsv($out, []); // Blank separator

        // 3. Applied Filters
        if (!empty($payload['filters']) && is_array($payload['filters'])) {
            fputcsv($out, ['[APPLIED FILTERS]']);
            foreach ($payload['filters'] as $f_label => $f_val) {
                if ($f_val !== null && $f_val !== '') {
                    fputcsv($out, ['  ' . $f_label . ':', $this->sanitizeForCsv($f_val)]);
                }
            }
            fputcsv($out, []);
        }

        // 4. Summary KPI Cards
        if (!empty($payload['summary']) && is_array($payload['summary'])) {
            fputcsv($out, ['[EXECUTIVE SUMMARY]']);
            foreach ($payload['summary'] as $s_item) {
                $label = !empty($s_item['label']) ? $s_item['label'] : 'Metric';
                $val = isset($s_item['value']) ? $s_item['value'] : '0';
                $meta = !empty($s_item['meta']) ? '(' . $s_item['meta'] . ')' : '';
                fputcsv($out, ['  ' . $label, $this->formatScalar($val, !empty($s_item['type']) ? $s_item['type'] : 'string', $currency), $meta]);
            }
            fputcsv($out, []);
        }

        // 5. Columns Header
        $columns = !empty($payload['columns']) ? $payload['columns'] : [];
        $header_row = [];
        foreach ($columns as $col) {
            $header_row[] = !empty($col['label']) ? $col['label'] : ucfirst(str_replace('_', ' ', $col['key']));
        }
        if (!empty($header_row)) {
            fputcsv($out, $header_row);
        }

        // 6. Data Rows
        $rows = !empty($payload['rows']) ? $payload['rows'] : [];
        foreach ($rows as $row) {
            $csv_row = [];
            foreach ($columns as $col) {
                $key = $col['key'];
                $val = '';
                if (is_object($row) && isset($row->$key)) {
                    $val = $row->$key;
                } elseif (is_array($row) && isset($row[$key])) {
                    $val = $row[$key];
                }
                $type = !empty($col['type']) ? $col['type'] : 'string';
                $csv_row[] = $this->formatCellValue($val, $type);
            }
            fputcsv($out, $csv_row);
        }

        // 7. Totals Row
        if (!empty($payload['totals']) && is_array($payload['totals'])) {
            $totals_row = [];
            $first = true;
            foreach ($columns as $col) {
                $key = $col['key'];
                if (isset($payload['totals'][$key])) {
                    $tval = $payload['totals'][$key];
                    $type = !empty($col['type']) ? $col['type'] : 'number';
                    $totals_row[] = $this->formatCellValue($tval, $type);
                } else {
                    $totals_row[] = $first ? 'TOTAL' : '';
                }
                $first = false;
            }
            fputcsv($out, $totals_row);
        }

        // 8. Notes / Confidentiality
        if (!empty($payload['notes'])) {
            fputcsv($out, []);
            fputcsv($out, ['Notes / Disclaimers:']);
            if (is_array($payload['notes'])) {
                foreach ($payload['notes'] as $note) {
                    fputcsv($out, ['* ' . $this->sanitizeForCsv($note)]);
                }
            } else {
                fputcsv($out, ['* ' . $this->sanitizeForCsv($payload['notes'])]);
            }
        }

        fclose($out);
        exit;
    }

    /**
     * Prevent CSV Formula Injection (OWASP security rule)
     * Prepends single quote if string starts with dangerous formula symbols: = + - @ \t \r
     */
    protected function sanitizeForCsv($value)
    {
        if (!is_string($value)) {
            return $value;
        }
        $trimmed = ltrim($value);
        if ($trimmed !== '' && in_array($trimmed[0], ['=', '+', '-', '@', "\t", "\r"])) {
            return "'" . $value;
        }
        return $value;
    }

    /**
     * Format cell value for CSV export
     */
    protected function formatCellValue($val, $type = 'string')
    {
        if ($val === null || $val === '') {
            return '';
        }

        switch ($type) {
            case 'currency':
                return is_numeric($val) ? number_format((float)$val, 2, '.', '') : $val;
            case 'number':
            case 'integer':
                return is_numeric($val) ? (string)$val : $val;
            case 'percentage':
                return is_numeric($val) ? number_format((float)$val, 2, '.', '') . '%' : $val;
            case 'date':
                if (is_numeric($val) && (int)$val > 100000) {
                    return date('Y-m-d', (int)$val);
                }
                return (string)$val;
            case 'datetime':
                if (is_numeric($val) && (int)$val > 100000) {
                    return date('Y-m-d H:i', (int)$val);
                }
                return (string)$val;
            default:
                return $this->sanitizeForCsv((string)$val);
        }
    }

    /**
     * Format scalar KPI summary value
     */
    protected function formatScalar($val, $type = 'string', $currency = 'BDT')
    {
        if ($type === 'currency' && is_numeric($val)) {
            return $currency . ' ' . number_format((float)$val, 2);
        }
        if ($type === 'integer' && is_numeric($val)) {
            return number_format((int)$val);
        }
        if ($type === 'percentage' && is_numeric($val)) {
            return number_format((float)$val, 2) . '%';
        }
        return (string)$val;
    }
}
